  const result=await api('/api/clip-text',{text,...(session.timeFormat?{time_format:session.timeFormat}:{})});
  if(clipTextSession!==session||!$('clipTextDialog').open)return;
  if(result.errors.length){$('clipTextMessage').textContent=result.errors.join('\n');return}
  const row=current?.draft.rows[session.index];
  if(current?.id!==session.id||selectedId!==session.id||openingBatchRequest!==session.navigation||!row||!clipTextEditable()||(session.rowId?(row.request_id||row.client_id)!==session.rowId:row!==session.row))throw Error('当前成片已变化，请关闭后重新识别');
