function timePart(i,n,clip,side,label){const fields=[['m','分',2],['s','秒',2],clip.time_format==='source_frames_v1'?['f','帧',3]:['ms','毫秒',3]];return `<span class="time-part">${fields.map(([key,name,width])=>`<input inputmode="numeric" maxlength="3" aria-label="片段 ${n+1} ${label} ${name}" data-row="${i}" data-clip="${n}" data-clip-part="${side}_${key}" value="${esc(padPart(clip[side+'_'+key],width))}">`).join('<span aria-hidden="true">:</span>')}</span>`}
