function renderEditor(){const d=current.draft;const structured=d.rows.some(r=>r.composition);const webForm=current.filename==='网页填写'||d.rows.some(r=>Array.isArray(r.clips));const plain=structured||webForm;const heading=document.querySelector('#editorTab h2');heading.textContent=structured?'编辑确认':'检查并编辑制作内容';heading.nextElementSibling.textContent=structured?'一条成片包含开头、至少一段剧情和结尾。剧情按填写顺序剪辑。':webForm?`每一条素材填写 Hook 和剪辑时间。时间用${d.editor_time_format==='source_frames_v1'?'分:秒:帧':'分:秒:毫秒'}。`:'按原表顺序保留片段、回溯和文案。每一行对应一条素材。';$('addRow').textContent=structured?'＋ 添加一条成片':'＋ 添加素材';document.querySelector('[data-tab="editor"]').textContent=structured?'编辑内容':'标准化内容';$('batchTitle').textContent=`${d.drama_id?d.drama_id+' · ':''}${d.drama_title||current.display_name||'未命名项目'}`;$('batchName').textContent=`${current.filename} / ${d.rows.length} 条素材`;$('metadata').innerHTML=inputField(plain?'剧 ID':'剧 ID（从表格识别）','drama_id',d.drama_id)+inputField('剧名（选填）','drama_title',d.drama_title)+inputField(plain?(current.filename==='网页填写'?'制作人 / 编导（制作人姓名会写进成片文件名）':'制作人 / 编导'):'制作人 / 编导（从 Excel 读取）','author',d.author,'placeholder="例如：徐明飞" required')+inputField('业务日期','business_date',d.business_date,webForm&&!structured?'type="date"':'')+inputField('素材类型','material_type',d.material_type)+inputField('制作标识（固定）','creator2','agent','readonly')+brandFields();
$('directorHint').textContent=d.source_author?`Excel 识别制作人：${d.source_author}。可在制作前修改，成片命名以确认后的姓名为准。`:current.filename==='网页填写'?'':'Excel 未识别到制作人，请补填实际编导姓名后再开始制作。';$('directorHint').hidden=!$('directorHint').textContent;$('warnings').innerHTML=current.warnings.length?`<div class="notice warning" style="margin-bottom:20px"><strong>${structured?'以下仅为核对提醒，不会阻止制作。剧名和开头字幕可留空。':'以下仅为核对提醒，不会阻止制作；确认内容无误后即可继续。剧名和 Hook 可留空。'}</strong><br>${current.warnings.map(esc).join('<br>')}</div>`:'';
$('requests').innerHTML=d.rows.map((r,i)=>r.composition?compositionCard(r,i):`<article class="request compact-request"><div class="requesthead"><div class="request-number"><label for="material-seq-${i}">素材</label><input id="material-seq-${i}" aria-label="素材序号" data-row="${i}" data-field="seq" value="${esc(r.seq)}"></div><button class="quiet danger" data-delete="${i}">删除</button></div><div class="requestbody material-flow"><section class="material-section opening-section"><div class="material-section-head"><span class="material-step">01</span><div><h3>开头字幕</h3><p>叠加在剧情开头 · 不需要可留空</p></div></div><div class="material-section-body"><label for="material-hook-${i}">字幕文案（Hook）</label><textarea id="material-hook-${i}" class="compact-hook" data-row="${i}" data-field="hook_text" placeholder="输入标题字幕，按 Enter 换行；不需要可留空">${esc(r.hook_text)}</textarea>${hookSettings(r,i)}</div></section><section class="material-section story-section"><div class="material-section-head"><span class="material-step">02</span><div><h3>剧情片段</h3><p>按填写顺序拼接 · 时间校对属于本段剧情</p></div></div><div class="material-section-body">${editorClips(r)?clipEditor({...r,clips:editorClips(r)},i):`<label for="material-timeline-${i}">剪辑时间线 <span class="hint">按行顺序执行 · 时间统一用 分:秒</span></label><textarea id="material-timeline-${i}" class="timeline" data-row="${i}" data-field="timeline_text" spellcheck="false">${esc(displayTimeline(r.timeline_text))}</textarea><p class="hint">时间线写法：EP1 00:15-02:04；EP4 表示全集；EP5 01:22 表示从该时间剪到结尾。字卡：字卡|文案|1.5s。</p>${/全集|-结尾/.test(r.timeline_text)?'<p class="hint pending-end">片尾按实际原片确定，以以下时长校对结果为准。</p>':''}${timingMarkup(i)}`}</div></section>${endingSettings(r,i)}</div><details class="request-extra"><summary>更多信息${r.notes?' · 有备注':''}</summary><div class="request-extra-body"><div class="fields">${rowField('需求编号','request_id',r.request_id,i)}${rowField('素材标题','title_cn',r.title_cn,i)}${rowField('结构','structure',r.structure,i)}${rowField('备注 / 特殊授权','notes',r.notes,i)}</div><p class="hint">来源：${esc(r.source||'手动添加')}</p>${r.conversion_notes?.length?`<p class="hint">${r.conversion_notes.map(esc).join('<br>')}</p>`:''}${r.original_cells?`<details><summary class="hint">Excel 原始内容</summary><p class="hint">${r.original_cells.filter(Boolean).map(esc).join(' · ')}</p></details>`:''}</div></details></article>`).join('')+(current.media_managed?(current.deleted_assets||[]).map(a=>`<p class="hint">已删除：${esc(a.title)} <button type="button" class="secondary" data-restore-asset="${esc(a.request_id)}">恢复素材</button></p>`).join(''):'');renderClipTextActions();renderValidation();$('saveState').textContent=!hasDraftData(d)?'标准化内容待填写':dirty?'有未保存修改 · 正片按时间线自动准备':(structured?'编辑内容已保存':'标准化内容已保存');controls();scheduleOriginalsLookup()}
const hookStyleNames={auto:'AI 自动风格',default:'清晰简洁',neon_reversal:'反转霓虹',danger_warning:'危险警示',ceo_luxury:'身份权力',emotional_diary:'情感日记',cold_mystery:'冷调悬疑',raw_conflict:'直接冲突'};
function hookOptions(r){return r.hook_options??={mode:'ai',style:'auto',position:'auto',duration_ms:null,manual_ranges:[]}}
function hookPlain(text){return String(text||'').replace(/\*\*(.+?)\*\*/gs,'$1').replace(/\s+/gu,' ').trim()}
function hookTokens(text){return Array.from(hookPlain(text).matchAll(/[\p{Script=Han}]|[\p{L}\p{N}]+(?:['’-][\p{L}\p{N}]+)*/gu),m=>({text:m[0],start:Array.from(hookPlain(text).slice(0,m.index)).length,end:Array.from(hookPlain(text).slice(0,m.index)).length+Array.from(m[0]).length}))}
function hookTypography(r,i){const o=hookOptions(r),custom=(o.font&&o.font!=='auto')||o.font_size!=null||o.text_color||o.accent_color;return `<details class="hook-typography" ${custom?'open':''}><summary>自定义字体与颜色 <span class="hint">${custom?'已自定义':'可选'}</span></summary><p class="hint">只覆盖你修改的项目，其余沿用风格默认。切换风格会保留自定义设置。</p><div class="fields">${hookSelect(i,'font','字体',o.font||'auto',{auto:'随风格',sans:'无衬线粗体',sans_italic:'无衬线粗斜体',serif:'衬线粗体',cjk:'思源黑体 · 中文'})}<div><label for="hook-size-${i}">字号（32～96，留空为自动）</label><input id="hook-size-${i}" type="number" min="32" max="96" step="1" placeholder="自动适配" data-row="${i}" data-hook-field="font_size" value="${o.font_size??''}"></div>${[['text_color','文字颜色','#ffffff'],...r.composition?[]:[['accent_color','强调颜色','#ffb347']]].map(([key,label,fallback])=>`<div><label for="hook-${key}-${i}">${label} <span class="hint" data-color-state="${i}-${key}">${o[key]?'自定义':'随风格'}</span></label><input id="hook-${key}-${i}" type="color" data-row="${i}" data-hook-field="${key}" value="${esc(o[key]||fallback)}"></div>`).join('')}</div><p class="hint">字号按 1080 宽画面设置，预览等比例缩放。${r.composition?'':'强调颜色只作用于画重点的词；选择「不强调」时不生效。'}</p><button type="button" class="quiet" data-row="${i}" data-reset-typography="${i}">清除自定义，恢复风格默认</button></details>`}
function hookSettings(r,i){const o=hookOptions(r),opening=r.composition?.opening;const style=opening?composeSelect(i,'opening.style','字幕风格',opening.style,composeStyles):hookSelect(i,'style','字幕风格',o.style,hookStyleNames);const behavior=opening?`${composeSelect(i,'opening.position','位置',opening.position,{top:'上方',middle:'中间',bottom:'下方'})}<div><label for="opening-duration-${i}">显示时长（秒）</label><input id="opening-duration-${i}" type="number" min="1" max="20" step="0.1" data-row="${i}" data-compose="opening.duration_s" value="${esc(opening.duration_s)}"></div>`:`${hookSelect(i,'mode','画重点',o.mode,{ai:'AI 理解语义',manual:'手工选词',none:'不强调'})}${hookSelect(i,'position','位置',o.position,{auto:'AI 避让人物和字幕',top:'上方',middle:'中间',bottom:'下方'})}<div><label for="hook-duration-${i}">显示时长（秒）</label><input id="hook-duration-${i}" type="number" min="1" max="20" step="0.1" placeholder="自动 4.5～9 秒" data-row="${i}" data-hook-field="duration_ms" value="${o.duration_ms==null?'':o.duration_ms/1000}"></div>`;return `<section class="hook-settings"><details class="hook-display" ${!opening&&o.mode==='manual'?'open':''}><summary>字幕样式与显示 <span class="hint">风格、字体、位置、时长</span></summary><div class="hook-display-body">${style}${hookTypography(r,i)}<div class="fields">${behavior}</div>${opening?'':`<div class="hook-word-tools" data-hook-words="${i}">${hookWords(r,i)}</div>`}<p class="hint">以上设置仅作用于开头字幕，显示时长可设为 1～20 秒，最多三行，支持 Enter 换行。</p></div></details><button type="button" class="secondary" data-row="${i}" data-hook-preview="${i}">保存并预览字幕</button><div class="hook-preview-result" data-hook-result="${i}">${hookPreviewMarkup(i)}</div></section>`}

function hookSelect(i,key,label,value,items){return `<div><label for="hook-${key}-${i}">${label}</label><select id="hook-${key}-${i}" data-row="${i}" data-hook-field="${key}">${Object.entries(items).map(([k,v])=>`<option value="${k}" ${value===k?'selected':''}>${v}</option>`).join('')}</select></div>`}
function hookWords(r,i){const o=hookOptions(r);if(o.mode!=='manual')return `<p class="hint">${o.mode==='none'?'整段文字使用文字颜色，不使用强调颜色。':'AI 选择需要强调的词，并使用强调颜色；也可改为手工选词。'}</p>`;return `<p class="hint">点击词语切换强调；相邻词会合并。</p><div class="hook-words">${hookTokens(r.hook_text).map((t,n)=>`<button type="button" aria-pressed="${(o.manual_ranges||[]).some(s=>s.start<=t.start&&s.end>=t.end)}" class="${(o.manual_ranges||[]).some(s=>s.start<=t.start&&s.end>=t.end)?'chosen':''}" data-hook-token="${i}" data-token="${n}">${esc(t.text)}</button>`).join('')}</div>`}
function hookPreviewMarkup(i){const job=current&&hookTasks.get(hookTaskKey(current.id,current.draft.rows[i]?.request_id));const preview=hookPreviews.get(hookPreviewKey(i));if(!preview){if(hookPending(job))return `<p class="hint" role="status">${job.status==='queued'?'Hook 预览已排队，轮到后自动处理；可以继续编辑。':esc(job.progress||'Hook 在后台处理中，可以继续编辑。')}</p>`;if(job?.status==='failed')return `<p class="notice warning">${esc(job.error||'Hook 预览未完成，可重试。')}</p>`;if(job?.status==='superseded')return '<p class="hint">设置已更新，旧预览未采用；保存后可重新预览。</p>';return '<p class="hint">保存后生成手机尺寸预览；尚未下载原片时展示排版。</p>';}const d=preview.decision;return `<img class="hook-preview-image" src="${preview.image}" alt="Hook 手机尺寸预览"><p class="hint">${esc(preview.notice)} 显示 ${seconds(d.duration_ms)} · ${esc(d.label_zh||hookStyleNames[d.style_id])}</p><p>${esc(d.emphasis?.reason||'')} ${esc((d.emphasis?.highlights||[]).map(h=>h.phrase).join(' · '))}</p>${[d.placement?.warning,d.readability_warning,d.sampling?.warning].filter(Boolean).map(w=>`<p class="notice warning">${esc(w)}</p>`).join('')}<p class="hint">${preview.sources_complete?'确认制作时，设置与原片仍匹配的预览会用于新版本。':'原片未齐或片尾未确定；制作时会重新检查画面位置。'}</p>`}
function invalidateHook(i){const key=hookTaskKey(current.id,current.draft.rows[i].request_id);hookInputEpochs.set(key,(hookInputEpochs.get(key)||0)+1);delete hookOptions(current.draft.rows[i]).preview_key;hookPreviews.delete(key);const box=document.querySelector(`[data-hook-result="${i}"]`);if(box)box.innerHTML='<p class="hint">设置已变化，请重新预览。</p>'}
function seconds(ms){return (Number(ms)/1000).toFixed(3)+' 秒'}
function clock(ms){if(ms===null||ms===undefined)return '待读取片尾';const n=Number(ms);return String(Math.floor(n/60000)).padStart(2,'0')+':'+((n%60000)/1000).toFixed(3).padStart(6,'0')}
function clipMillis(clip,side){if(clip.time_format)return null;const values=['m','s','ms'].map(key=>{const text=String(clip[side+'_'+key]??'').trim();return text===''?'0':text});if(values.some(value=>!/^\d{1,3}$/.test(value)))return null;const [minutes,secs,millis]=values.map(Number);if(secs>59||millis>999||minutes>999)return null;return minutes*60000+secs*1000+millis}
function localTiming(row){const segments=[];let total=0;(row.clips||[]).forEach(clip=>{const episode=String(clip.episode||'').replace(/^ep/i,'').trim();const start=clipMillis(clip,'start'),end=clipMillis(clip,'end');if(!/^[1-9]\d{0,2}$/.test(episode)||Number(episode)>500||start===null||end===null||end<=start)return;segments.push({segment:segments.length+1,type:'episode',episode:'EP'+Number(episode),start_ms:start,end_ms:end,duration_ms:end-start,error:'',source_status:'missing'});total+=end-start});return {segments,planned_duration_ms:total,known_duration_ms:total,pending_endings:0}}
function mergedTiming(local,server){if(!server)return local;return {...local,segments:local.segments.map((segment,index)=>{const remote=(server.segments||[])[index];if(!remote||remote.episode!==segment.episode||remote.start_ms!==segment.start_ms||remote.end_ms!==segment.end_ms)return segment;return {...segment,error:remote.error||'',source_status:remote.source_status||segment.source_status,source_duration_ms:remote.source_duration_ms}})}}
function timingTable(t,hint){const invalid=t.segments.some(s=>s.error),failed=t.segments.filter(s=>s.source_status==='failed').length,pending=t.segments.filter(s=>!s.error&&s.source_status!=='failed'&&(s.duration_ms===null||['missing','waiting','queued','downloading','checking'].includes(s.source_status))).length;const summary=!t.segments.length?'填写集号和时间后显示时长':invalid?'选段需要核对':t.pending_endings?'已确定 '+seconds(t.known_duration_ms)+'，另有 '+t.pending_endings+' 段待读取片尾':'预计总时长 '+seconds(t.planned_duration_ms);const rows=t.segments.length?t.segments.map(s=>`<tr><td>${s.segment}</td><td>${esc(s.type==='episode'?s.episode:'字卡：'+s.text)}</td><td>${s.type==='episode'?clock(s.start_ms):'—'}</td><td>${s.type==='episode'?clock(s.end_ms):'—'}</td><td>${s.duration_ms===null?'待核对':seconds(s.duration_ms)}</td><td>${esc(s.error||({missing:'等待正片',waiting:'等待下载位置',queued:'正片下载排队中',downloading:'正在下载正片',failed:'下载失败，可重试',checking:'正在读取时长',ready:s.type==='episode'?'已核对 · '+seconds(s.source_duration_ms):'字卡'}[s.source_status]||'待核对'))}</td></tr>`).join(''):'<tr><td colspan="6">填好一段集号和时间后，这里显示时长。</td></tr>';return `<details class="timing-explanation" open data-needs-review="${invalid||failed?'1':'0'}"><summary>时间解析校对 · ${summary}${failed?' · '+failed+' 段下载失败':''}${pending?' · '+pending+' 段待核对':''}</summary><p class="hint">${hint}</p><div class="timing-table"><table><thead><tr><th>片段</th><th>来源</th><th>起点</th><th>终点</th><th>计划时长</th><th>原片核对</th></tr></thead><tbody>${rows}${t.ending_duration_ms?`<tr><td>结尾</td><td>静态画面</td><td>—</td><td>—</td><td>${seconds(t.ending_duration_ms)}</td><td>追加 · 静音</td></tr>`:''}</tbody></table></div></details>`}
function timingMarkup(i){const original=current.draft.rows[i],row={...original,clips:editorClips(original)};const server=(current.timing_explanation||[]).find(t=>t.request_id===row.request_id);if(row.clips?.some(c=>c.time_format==='source_frames_v1')){const lines=row.clips.map((c,n)=>{const format=side=>['m','s',c.time_format==='source_frames_v1'?'f':'ms'].map((key,j)=>padPart(c[side+'_'+key],j===2?3:2)).join(':');return `<tr><td>${n+1}</td><td>EP${esc(c.episode)}</td><td>${esc(format('start'))}</td><td>${esc(format('end'))}</td></tr>`}).join('');return `<div data-timing-index="${i}"><details class="timing-explanation" open><summary>时间解析校对 · 分:秒:帧</summary><p class="hint">帧从 0 开始，结束帧保留。请按原片填写分、秒、帧；旧项目时间保持原格式。</p><div class="timing-table"><table><thead><tr><th>片段</th><th>来源</th><th>开始画面</th><th>结束画面</th></tr></thead><tbody>${lines}</tbody></table></div></details></div>`}if(Array.isArray(row.clips))return `<div data-timing-index="${i}">${timingTable(withEndingTiming(mergedTiming(localTiming(row),server),original),'按填写的分:秒:毫秒计算，改时间后立即更新。原片就绪后核对片长。')}</div>`;if(!server)return `<div data-timing-index="${i}"><p class="hint">保存并校验后显示时间解析说明。</p></div>`;return `<div data-timing-index="${i}">${timingTable(withEndingTiming(server,original),'请对照 Excel 原文核对。原片就绪后自动更新片尾；修改时间线后需保存。')}</div>`}
function refreshClipTiming(i){const box=document.querySelector(`[data-timing-index="${i}"]`);if(!box)return;const markup=timingMarkup(i);if(box.timingMarkup===markup)return;const open=box.querySelector('details')?.open;box.outerHTML=markup;const updated=document.querySelector(`[data-timing-index="${i}"]`);updated.timingMarkup=markup;const details=updated.querySelector('details');if(details&&open!==undefined)details.open=open||details.dataset.needsReview==='1'}
function refreshTiming(){for(const box of document.querySelectorAll('[data-timing-index]'))refreshClipTiming(Number(box.dataset.timingIndex))}

function rowField(label,key,value,index){return `<div><label>${esc(label)}</label><input ${current?.media_managed&&key==='request_id'?'readonly':''} data-row="${index}" data-field="${key}" value="${esc(value)}"></div>`}
function renderPlan(){if(!$('planBox'))return;const p=current?.plan;$('planBox').innerHTML=p?`<h2>本批次的正片准备计划</h2><p>优先获取 EP1～EP10 的实际可用正片；只有 8 集的剧按 8 集处理。${p.extra.length?`本批引用后续集数，获取上限扩展到 EP${p.episode_limit}。`:''}</p><div class="hint">剪辑必须用到</div><div class="chips">${p.required.map(ep=>`<span class="chip">${esc(ep)}</span>`).join('')||'<span class="hint">仅字卡内容</span>'}</div><p class="hint">已有正片自动去重，所需集数未到齐时会暂停制作并提示。</p>`:'<h2>正片准备计划</h2><p>修正标准化内容并保存后，将按时间线自动计算所需集数。</p>'}
let originalsTicket=0;
let originalsDownload={running:false,stopped:false,abort:null,frames:[],text:'',ratio:0};
function originalSize(bytes){const n=Number(bytes)||0;if(n<=0)return '';if(n<1024*1024)return `${Math.max(1,Math.round(n/1024))} KB`;return `${(n/1024/1024).toFixed(n>=10*1024*1024?0:1)} MB`}
function enteredDramaId(){const field=document.querySelector('#metadata [data-meta="drama_id"]');return String((field&&field.value)||current?.draft?.drama_id||'').trim()}
function originalUrl(episode){return appUrl('/api/batches/'+current.id+'/originals/'+encodeURIComponent(episode)+'?drama_id='+encodeURIComponent(enteredDramaId()))}
function originalFileUrl(episode){return appUrl('/api/batches/'+current.id+'/originals/'+encodeURIComponent(episode)+'/file?drama_id='+encodeURIComponent(enteredDramaId()))}
function originalsEpisodes(){return [...document.querySelectorAll('#originalsBox [data-original-pick]')].map(el=>el.dataset.originalPick)}
function originalsPicked(){return [...document.querySelectorAll('#originalsBox [data-original-pick]:checked')].map(el=>el.dataset.originalPick)}
function refreshOriginalsSelection(){const picks=[...document.querySelectorAll('#originalsBox [data-original-pick]')],selected=picks.filter(el=>el.checked).length,all=$('originalsSelectAll');if(all){all.checked=picks.length>0&&selected===picks.length;all.indeterminate=selected>0&&selected<picks.length}const chosen=$('originalsDownloadSelected');if(chosen)chosen.disabled=originalsDownload.running||selected===0;const every=$('originalsDownloadAll');if(every)every.disabled=originalsDownload.running||picks.length===0;const choose=$('originalsChooseDir');if(choose)choose.disabled=originalsDownload.running;const note=$('originalsSelectedCount');if(note)note.textContent=selected?`已选 ${selected} 集`:'未选择'}
function originalsDirSupported(){return window.isSecureContext&&typeof window.showDirectoryPicker==='function'}
function originalsDirDb(){return new Promise((resolve,reject)=>{const request=indexedDB.open('exactcut-originals',1);request.onupgradeneeded=()=>request.result.createObjectStore('dirs');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
