function validDramaId(value){return /^\d{6}$/.test(value)&&Number(value)>=101050&&Number(value)<=999999}
function episodeNumbers(labels){return labels.map(label=>Number(String(label).replace(/^EP/i,''))).filter(number=>Number.isInteger(number)&&number>0).sort((a,b)=>a-b)}
