function draftEpisodeLabels(){const found=new Set();const add=value=>{const text=String(value||'').replace(/^ep/i,'').trim();if(/^[1-9]\d{0,2}$/.test(text))found.add(Number(text))};for(const row of current?.draft?.rows||[]){for(const clip of row.clips||[])add(clip.episode);for(const plot of row.composition?.plots||[])add(plot.episode)}return [...found].sort((a,b)=>a-b).map(number=>'EP'+number)}
