function originalsStatusText(){if(originalsLookup.status==='loading')return '正在检查阿里云原片…';if(originalsLookup.status==='error')return '原片列表暂时读不到';if(originalsLookup.status==='missing')return '物料库里暂未找到这部剧的原片';if(originalsLookup.status==='ready'){const missing=missingDraftEpisodes();let text=`有 ${originalsLookup.episodes.length} 集原片（${episodeSpan(originalsLookup.episodes)}）`;if(missing.length)text+=`。时间线里的 ${missing.join('、')} 不在物料库`;if(originalsLookup.notice)text+=`。${originalsLookup.notice}`;return text}return ''}
function paintOriginalsAvailability(){const button=$('originalsOpen'),note=$('originalsStatus'),box=$('originalsLookup'),retry=$('originalsLookupRetry');if(!button||!note||!box)return;const drama=enteredDramaId(),currentLookup=originalsLookup.batchId===current?.id&&originalsLookup.drama===drama;button.disabled=!(currentLookup&&originalsLookup.status==='ready'&&originalsLookup.episodes.length);button.textContent='下载原片';const text=currentLookup?originalsStatusText():'';note.textContent=text;box.hidden=!text;box.className='originals-lookup'+(currentLookup&&(originalsLookup.status==='missing'||originalsLookup.status==='error'||missingDraftEpisodes().length)?' missing':'');if(retry)retry.hidden=!(currentLookup&&originalsLookup.status==='error')}
