const publishSubmissions=new Map();
function submitPublication(intent){
 const {id,request,request_id,version_id,sha256,managed}=intent;
 const previous=publishSubmissions.get(id)||Promise.resolve();
 const submission=previous.catch(()=>{}).then(async()=>{
  const asset=current?.assets.find(a=>a.request_id===request_id);
  if(selectedId!==id||current?.id!==id||request!==openingBatchRequest||openingBatchId)throw Error('项目页面已切换，请重新预览确认上传');
  if(dirty)throw Error('请先保存当前修改，再确认上传');
  if(!asset||asset.version_id!==version_id||asset.sha256!==sha256||!asset.preview)throw Error('成片版本已变化，请重新预览确认');
  if((managed&&!current.media_delivery_enabled)||(!managed&&activeStatuses.filter(s=>s!=='publishing').includes(current.runtime.status))||current.runtime.archived||current.runtime.paused||current.runtime.status==='resume_queued'||asset.status==='fbbm_ready'||['pending','upload_queued','uploading','fbbm_queued','unverified'].includes(asset.status)||asset.deliveries?.some(d=>['pending','upload_queued','uploading','fbbm_queued','unverified'].includes(d.status)))throw Error('当前交付状态不允许再次提交，请检查素材进度');
  const result=await api(`/api/batches/${id}/publish`,{request_id,sha256,...(managed?{version_id}: {})});
  await refreshSelectedBatch(true,{id,request,detail:result});
  toast('预览确认已记录，已加入上传队列，可继续提交其他素材');
 });
 publishSubmissions.set(id,submission);
 return submission.finally(()=>{if(publishSubmissions.get(id)===submission)publishSubmissions.delete(id)});
}
