function clearDeletedSelection(id){
 batchDetails.delete(id);
 if(selectedId===id){selectedId=null;current=null;dirty=false;assetKeys='';history.replaceState(null,'',location.pathname);showEmptyWorkspace()}
 if(localStorage.getItem('exactcut.batch')===id)localStorage.removeItem('exactcut.batch');
}
function controlMessage(result,action,fallback){const prefix={pause:'已请求暂停',archive:'已归档'}[action],said=result?.runtime?.events?.at(-1)?.message;return prefix&&said?.startsWith(prefix)?said:fallback}
async function sidebarAction(button){
 const id=button.dataset.id,action=button.dataset.batchAction,item=batchCache.find(b=>b.id===id);
 if(!item)return;
 if(selectedId===id&&dirty){toast('请先保存标准化内容，再操作项目',true);return}
 if(action==='delete'&&!item.media_managed&&!window.confirm(`永久删除 ${item.drama_id} · ${item.drama_title||item.filename}？\n\n本项目的制作内容、成片及记录将永久删除，无法复原。共用原片和已上传到 FBBM 的素材不受影响。`))return;
 await operation(button,async()=>{
  const result=await api(`/api/batches/${id}/${action}`,action==='delete'?{confirmation:id}:{});
  batchDetails.delete(id);
  if(action==='delete')clearDeletedSelection(id);
  else if(selectedId===id){current=result;renderRuntime()}
  await refreshBatches();toast(action==='delete'?(item.media_managed?'项目已逻辑删除，可在归档列表恢复':'项目已永久删除'):action==='archive'?controlMessage(result,action,'已归档，可在已归档列表复原'):'项目已复原到当前项目');
 });
}

